<?php
declare(strict_types=1);
namespace Morshed\Product;
use Morshed\Core\{Database,Security,Audit,Problem};
final class Content
{
    private Policy $policy;
    public function __construct(private Database $db,private Audit $audit){$this->policy=new Policy($db);}
    private function write(array $a,bool $system,callable $fn):mixed
    {return $this->db->tx(function()use($a,$system,$fn){$this->db->one('SELECT id FROM m_installation WHERE id=1 FOR UPDATE');$this->policy->admin($a,$system);return $fn();});}
    public function terms(bool $all=false):array{return $this->db->all('SELECT t.*,p.title AS parent_title FROM m_terms t LEFT JOIN m_terms p ON p.id=t.parent_id'.($all?'':' WHERE t.active=1').' ORDER BY t.kind,t.title');}
    public function term(array $a,array $d):string
    {return $this->write($a,false,function()use($a,$d){$kind=Policy::choice($d['kind']??'', ['topic','issue']);$title=Policy::text($d['title']??'',160);$id=($d['id']??'')?:Security::id();$parent=($d['parent_id']??'')?:null;
        if($kind==='issue'&&(!$parent||!$this->db->one("SELECT id FROM m_terms WHERE id=? AND kind='topic' AND active=1",[$parent]))){throw new Problem('INVALID_TOPIC','موضوع فعال برای مسئله انتخاب کنید.');}
        if($kind==='topic'){$parent=null;}
        $old=$this->db->one('SELECT * FROM m_terms WHERE id=?',[$id]);if($this->db->one('SELECT id FROM m_terms WHERE kind=? AND title=? AND id<>?',[$kind,$title,$id])){throw new Problem('CONFLICT','این عنوان طبقه‌بندی از قبل وجود دارد.',409);}if($old&&$old['kind']!==$kind){throw new Problem('CONFLICT','نوع طبقه‌بندی قابل تغییر نیست.',409);}
        if($old){$this->db->run('UPDATE m_terms SET title=?,parent_id=?,active=? WHERE id=?',[$title,$parent,Policy::integer($d['active']??1,0,1),$id]);}else{$this->db->run('INSERT INTO m_terms(id,kind,title,parent_id) VALUES(?,?,?,?)',[$id,$kind,$title,$parent]);}
        $this->audit->add($a['user_id'],'admin','taxonomy.saved',$id);return $id;});}
    public function invite(array $a,array $d):string
    {return $this->write($a,true,function()use($a,$d){$uid=$d['user_id']??'';if(!$this->db->one("SELECT id FROM m_users WHERE id=? AND status='active'",[$uid])){throw new Problem('NOT_FOUND','ابتدا کاربر باید حساب تأییدشده داشته باشد.',404);}
        if($this->db->one('SELECT user_id FROM m_mentors WHERE user_id=?',[$uid])){throw new Problem('CONFLICT','این کاربر قبلاً دعوت شده است.',409);}
        $this->db->run('INSERT INTO m_mentors(user_id,headline,bio,invited_at,updated_at) VALUES(?,?,?,?,?)',[$uid,Policy::text($d['headline']??'',180),Policy::text($d['bio']??'',20000),time(),time()]);
        $this->db->run('INSERT INTO m_schedule_settings(mentor_id) VALUES(?)',[$uid]);$this->audit->notify($uid,'دعوت به مرشد','برای پذیرش دعوت، به پنل مرشد در حساب خود مراجعه کنید.','/mentor');$this->audit->add($a['user_id'],'admin','mentor.invited',$uid);return $uid;});}
    public function mentorState(array $a,string $uid,string $state):void
    {$this->write($a,true,function()use($a,$uid,$state){Policy::choice($state,['active','restricted','review']);$m=$this->db->one('SELECT * FROM m_mentors WHERE user_id=? FOR UPDATE',[$uid]);if(!$m){throw new Problem('NOT_FOUND','مرشد پیدا نشد.',404);}
        $this->db->run('UPDATE m_mentors SET status=?,updated_at=? WHERE user_id=?',[$state,time(),$uid]);$this->audit->notify($uid,'وضعیت مرشد','وضعیت پروفایل مرشد شما تغییر کرد.','/mentor');$this->audit->add($a['user_id'],'admin','mentor.'.$state,$uid);});}
    public function acceptInvite(array $a):void
    {$this->db->tx(function()use($a){$this->db->one('SELECT id FROM m_installation WHERE id=1 FOR UPDATE');$m=$this->policy->mentor($a);$legal=$this->db->one("SELECT version_id FROM m_legal_publications WHERE document_key='base'");if(!empty($legal['version_id'])&&!$this->db->one('SELECT user_id FROM m_user_acceptances WHERE user_id=? AND version_id=?',[$a['user_id'],$legal['version_id']])){throw new Problem('TERMS_REQUIRED','ابتدا آخرین قوانین پایه را در حساب بپذیرید.',409);}if($m['status']!=='invited'){throw new Problem('CONFLICT','دعوت قبلاً رسیدگی شده است.',409);}$this->db->run("UPDATE m_mentors SET status='review',accepted_at=?,updated_at=? WHERE user_id=?",[time(),time(),$a['user_id']]);$this->audit->add($a['user_id'],'site','mentor.invite_accepted',$a['user_id']);});}
    public function mentorProfile(array $a,array $d):void
    {$this->db->tx(function()use($a,$d){$this->db->one('SELECT id FROM m_installation WHERE id=1 FOR UPDATE');$m=$this->policy->mentor($a);if(!$m['accepted_at']){throw new Problem('INVITE_NOT_ACCEPTED','دعوت را بپذیرید.',409);}
        $terms=$d['terms']??[];if(!is_array($terms)||count($terms)>20){throw new Problem('INVALID_INPUT','حداکثر بیست موضوع مجاز است.');}foreach($terms as $t){if(!is_string($t)||!$this->db->one('SELECT id FROM m_terms WHERE id=? AND active=1',[$t])){throw new Problem('INVALID_TOPIC','موضوع معتبر نیست.');}}
        $this->db->run("UPDATE m_mentors SET headline=?,bio=?,status='review',updated_at=? WHERE user_id=?",[Policy::text($d['headline']??'',180),Policy::text($d['bio']??'',20000),time(),$a['user_id']]);$this->db->run('DELETE FROM m_mentor_terms WHERE mentor_id=?',[$a['user_id']]);foreach(array_unique($terms) as $t){$this->db->run('INSERT INTO m_mentor_terms VALUES(?,?)',[$a['user_id'],$t]);}$this->audit->add($a['user_id'],'site','mentor.profile_review_requested',$a['user_id']);});}
    private function mentorFilter(array $d,bool $admin):array
    {
        $q=Policy::query($d['q']??'');$args=[$q,$q,$q,$q,$q,$q];$where=$admin?'1=1':"m.status='active' AND u.status='active'";
        $where.=" AND (REPLACE(REPLACE(m.headline,'ي','ی'),'ك','ک') LIKE ? OR REPLACE(REPLACE(m.bio,'ي','ی'),'ك','ک') LIKE ? OR REPLACE(REPLACE(u.display_name,'ي','ی'),'ك','ک') LIKE ? OR EXISTS(SELECT 1 FROM m_mentor_terms mt JOIN m_terms t ON t.id=mt.term_id WHERE mt.mentor_id=m.user_id AND t.active=1 AND REPLACE(REPLACE(t.title,'ي','ی'),'ك','ک') LIKE ?) OR EXISTS(SELECT 1 FROM m_experiences e JOIN m_experience_versions v ON v.id=e.public_version_id AND v.experience_id=e.id WHERE e.mentor_id=m.user_id AND (REPLACE(REPLACE(v.title,'ي','ی'),'ك','ک') LIKE ? OR REPLACE(REPLACE(v.body,'ي','ی'),'ك','ک') LIKE ?)))";
        foreach(['term','topic','issue'] as $key){$term=$d[$key]??'';if(is_string($term)&&$term!==''){$where.=' AND EXISTS(SELECT 1 FROM m_mentor_terms mt JOIN m_terms t ON t.id=mt.term_id WHERE mt.mentor_id=m.user_id AND t.active=1 AND (t.id=? OR t.parent_id=?))';$args[]=$term;$args[]=$term;}}
        if(isset($d['accepting'])&&$d['accepting']!==''){$paused=1-Policy::integer($d['accepting'],0,1);$where.=' AND s.acceptance_paused=?';$args[]=$paused;}
        return [" FROM m_mentors m JOIN m_users u ON u.id=m.user_id JOIN m_schedule_settings s ON s.mentor_id=m.user_id WHERE $where",$args];
    }
    public function mentorTotal(array $d=[]):int{[$sql,$args]=$this->mentorFilter($d,false);return (int)$this->db->run('SELECT COUNT(*)'.$sql,$args)->fetchColumn();}
    public function mentors(array $d=[],bool $admin=false):array
    {[$sql,$args]=$this->mentorFilter($d,$admin);$sort=Policy::choice($d['sort']??'relevant',['relevant','latest']);$order='m.updated_at DESC,m.user_id';if($sort==='relevant'&&is_string($d['q']??null)&&trim($d['q'])!==''){$order="(REPLACE(REPLACE(m.headline,'ي','ی'),'ك','ک') LIKE ? OR REPLACE(REPLACE(u.display_name,'ي','ی'),'ك','ک') LIKE ?) DESC,".$order;$args[]=Policy::query($d['q']);$args[]=Policy::query($d['q']);}$page=Policy::integer($d['page']??1,1,10000);return (new Catalog($this->db))->mentors($this->db->all('SELECT m.*,u.display_name,s.acceptance_paused,s.access_scope'.$sql.' ORDER BY '.$order.' LIMIT 21 OFFSET '.(($page-1)*20),$args));}
    public function mentor(string $id):array
    {$m=$this->db->one("SELECT m.*,u.display_name,s.acceptance_paused,s.access_scope FROM m_mentors m JOIN m_users u ON u.id=m.user_id JOIN m_schedule_settings s ON s.mentor_id=m.user_id WHERE m.user_id=? AND m.status='active' AND u.status='active'",[$id]);if(!$m){throw new Problem('NOT_FOUND','مرشد منتشرشده پیدا نشد.',404);}return (new Catalog($this->db))->mentors([$m])[0];}
    public function saveExperience(array $a,array $d):array
    {if(array_key_exists('problem',$d)){return (new ExperienceCases($this->db,$this->audit))->save($a,$d);}return $this->db->tx(function()use($a,$d){$this->db->one('SELECT id FROM m_installation WHERE id=1 FOR UPDATE');$m=$this->policy->mentor($a);if(!$m['accepted_at']){throw new Problem('INVITE_NOT_ACCEPTED','ابتدا دعوت را بپذیرید.',409);}$uid=$a['user_id'];$eid=($d['experience_id']??'')?:Security::id();$e=$this->db->one('SELECT * FROM m_experiences WHERE id=? FOR UPDATE',[$eid]);if($e&&$e['mentor_id']!==$uid){throw new Problem('ACCESS_DENIED','این تجربه متعلق به شما نیست.',403);}
        $title=Policy::text($d['title']??'',180);$body=Policy::text($d['body']??'',60000);$term=($d['term_id']??'')?:null;if($term&&!$this->db->one('SELECT id FROM m_terms WHERE id=? AND active=1',[$term])){throw new Problem('INVALID_TOPIC','موضوع معتبر نیست.');}
        if(!$e){$this->db->run('INSERT INTO m_experiences(id,mentor_id,created_at) VALUES(?,?,?)',[$eid,$uid,time()]);}
        $latest=$this->db->one('SELECT id,version_no FROM m_experience_versions WHERE experience_id=? ORDER BY version_no DESC LIMIT 1',[$eid]);if(($d['base_version_id']??'')!==($latest['id']??'')){throw new Problem('STALE_VERSION','تجربه تغییر کرده است؛ آخرین نسخه را دوباره باز کنید.',409);}
        $id=Security::id();$n=($latest?(int)$latest['version_no']:0)+1;$this->db->run('INSERT INTO m_experience_versions(id,experience_id,version_no,title,body,term_id,review_note,created_at) VALUES(?,?,?,?,?,?,?,?)',[$id,$eid,$n,$title,$body,$term,'',time()]);$assets=$d['asset_ids']??[];if(!is_array($assets)||count($assets)>5){throw new Problem('INVALID_FILE','حداکثر پنج مستند برای هر نسخه مجاز است.');}foreach($assets as $asset){if(!is_string($asset)) {throw new Problem('INVALID_FILE','شناسه فایل معتبر نیست.');}}foreach(array_unique($assets) as $asset){if(!$this->db->one('SELECT id FROM m_content_assets WHERE id=? AND owner_id=?',[$asset,$uid])){throw new Problem('ACCESS_DENIED','فایل مستند متعلق به شما نیست.',403);}$this->db->run('INSERT INTO m_experience_assets VALUES(?,?)',[$id,$asset]);}$this->audit->add($uid,'site','experience.version_created',$id);return ['id'=>$id,'experience_id'=>$eid];});}
    public function submit(array $a,string $id):void
    {$this->db->tx(function()use($a,$id){$this->db->one('SELECT id FROM m_installation WHERE id=1 FOR UPDATE');$this->policy->mentor($a);$v=$this->db->one('SELECT v.*,e.mentor_id FROM m_experience_versions v JOIN m_experiences e ON e.id=v.experience_id WHERE v.id=? FOR UPDATE',[$id]);if(!$v||$v['mentor_id']!==$a['user_id']){throw new Problem('ACCESS_DENIED','نسخه متعلق به شما نیست.',403);}if($v['status']!=='draft'){throw new Problem('INVALID_STATE','فقط پیش‌نویس ارسال می‌شود.',409);}$this->db->run("UPDATE m_experience_versions SET status='submitted' WHERE id=?",[$id]);$this->audit->add($a['user_id'],'site','experience.submitted',$id);});}
    public function review(array $a,string $id,string $decision,string $note):void
    {$this->write($a,false,function()use($a,$id,$decision,$note){Policy::choice($decision,['approved','changes','rejected']);$note=Policy::text($note,10000,$decision==='approved'?0:1);$v=$this->db->one('SELECT * FROM m_experience_versions WHERE id=? FOR UPDATE',[$id]);if(!$v||$v['status']!=='submitted'){throw new Problem('INVALID_STATE','نسخه در صف بررسی نیست.',409);}
        if($decision==='approved'){$case=new ExperienceCases($this->db,$this->audit);$details=$case->details($id);if($details&&($missing=$case->missing($details))){throw new Problem('EXPERIENCE_INCOMPLETE','برای انتشار تکمیل کنید: '.implode('، ',$missing),409);}$latest=$this->db->one('SELECT id FROM m_experience_versions WHERE experience_id=? ORDER BY version_no DESC LIMIT 1',[$v['experience_id']]);if($latest['id']!==$id){throw new Problem('STALE_VERSION','فقط آخرین نسخه قابل انتشار است.',409);}$this->db->run('UPDATE m_experiences SET public_version_id=? WHERE id=?',[$id,$v['experience_id']]);}
        $this->db->run('UPDATE m_experience_versions SET status=?,review_note=?,reviewed_by=?,reviewed_at=? WHERE id=?',[$decision,$note,$a['user_id'],time(),$id]);$owner=$this->db->run('SELECT mentor_id FROM m_experiences WHERE id=?',[$v['experience_id']])->fetchColumn();$this->audit->add($a['user_id'],'admin','experience.'.$decision,$id);});}
    public function unpublish(array $a,string $id):void
    {$this->write($a,false,function()use($a,$id){$this->db->run('UPDATE m_experiences SET public_version_id=NULL WHERE id=?',[$id]);$this->audit->add($a['user_id'],'admin','experience.unpublished',$id);});}
    private function experienceFilter(array $d):array
    {$q=Policy::query($d['q']??'');$args=[$q,$q,$q,$q];$where="m.status='active' AND u.status='active' AND (REPLACE(REPLACE(v.title,'ي','ی'),'ك','ک') LIKE ? OR REPLACE(REPLACE(v.body,'ي','ی'),'ك','ک') LIKE ? OR REPLACE(REPLACE(u.display_name,'ي','ی'),'ك','ک') LIKE ? OR REPLACE(REPLACE(t.title,'ي','ی'),'ك','ک') LIKE ?)";
        if(is_string($d['mentor_id']??null)&&$d['mentor_id']!==''){$where.=' AND e.mentor_id=?';$args[]=$d['mentor_id'];}foreach(['term','topic','issue'] as $key){if(is_string($d[$key]??null)&&$d[$key]!==''){$where.=' AND t.active=1 AND (t.id=? OR t.parent_id=?)';$args[]=$d[$key];$args[]=$d[$key];}}
        if(\Morshed\Core\Upgrade::ready($this->db)){foreach(['outcome','target_audience','constraints'] as $filter){if(!empty($d[$filter])){$where.=' AND EXISTS(SELECT 1 FROM m_experience_details x WHERE x.version_id=v.id AND x.'.$filter.($filter==='outcome'?'=?':' LIKE ?').')';$args[]=$filter==='outcome'?Policy::choice($d[$filter],['success','failure','mixed','unknown']):Policy::query($d[$filter]);}}}
        return [" FROM m_experiences e JOIN m_experience_versions v ON v.id=e.public_version_id AND v.experience_id=e.id JOIN m_mentors m ON m.user_id=e.mentor_id JOIN m_users u ON u.id=m.user_id LEFT JOIN m_terms t ON t.id=v.term_id WHERE $where",$args];}
    public function experienceTotal(array $d=[]):int{[$sql,$args]=$this->experienceFilter($d);return (int)$this->db->run('SELECT COUNT(*)'.$sql,$args)->fetchColumn();}
    public function experiences(array $d=[]):array
    {[$sql,$args]=$this->experienceFilter($d);$sort=Policy::choice($d['sort']??'relevant',['relevant','latest']);$order='v.reviewed_at DESC,e.id';if($sort==='relevant'&&is_string($d['q']??null)&&trim($d['q'])!==''){$order="(REPLACE(REPLACE(v.title,'ي','ی'),'ك','ک') LIKE ?) DESC,".$order;$args[]=Policy::query($d['q']);}$page=Policy::integer($d['page']??1,1,10000);$extra=\Morshed\Core\Upgrade::ready($this->db)?', (SELECT summary FROM m_experience_details WHERE version_id=v.id) AS summary, (SELECT outcome FROM m_experience_details WHERE version_id=v.id) AS outcome':'';return (new Catalog($this->db))->experiences(array_map(fn($v)=>$this->publicNarrative($v),$this->db->all('SELECT e.id,e.mentor_id,v.id AS version_id,v.title,v.body,v.version_no,t.title AS term_title,u.display_name'.$extra.$sql.' ORDER BY '.$order.' LIMIT 21 OFFSET '.(($page-1)*20),$args)));}
    public function experience(string $id):array
    {$v=$this->db->one("SELECT e.id,e.mentor_id,v.id AS version_id,v.title,v.body,v.version_no,v.term_id,u.display_name FROM m_experiences e JOIN m_experience_versions v ON v.id=e.public_version_id AND v.experience_id=e.id JOIN m_mentors m ON m.user_id=e.mentor_id JOIN m_users u ON u.id=m.user_id WHERE e.id=? AND m.status='active' AND u.status='active'",[$id]);if(!$v){throw new Problem('NOT_FOUND','تجربه منتشرشده پیدا نشد.',404);}return (new Catalog($this->db))->experiences([$this->publicNarrative($v)])[0];}
    private function publicNarrative(array $record):array
    {
        $case=(new ExperienceCases($this->db,$this->audit))->details($record['version_id'],true);
        if($case){$parts=[];foreach(ExperienceCases::NARRATIVE as $key=>$label){if(trim($case[$key]??'')!==''){$parts[]=$label."\n".$case[$key];}}$record['body']=implode("\n\n",$parts);if(array_key_exists('summary',$record)){$record['summary']=$case['problem']??'';}}
        unset($record['outcome']);return $record;
    }
    public function saveStore(array $a,array $blocks):string
    {return $this->write($a,false,function()use($a,$blocks){if(count($blocks)>20){throw new Problem('INVALID_INPUT','حداکثر بیست بلوک مجاز است.');}$clean=[];$heroCount=0;foreach($blocks as $b){if(!is_array($b)){throw new Problem('INVALID_INPUT','بلوک معتبر نیست.');}$type=Policy::choice($b['type']??'', ['mentors','experiences','topics','text','hero']);$ids=$b['ids']??[];if(!is_array($ids)||count($ids)>20){throw new Problem('INVALID_INPUT','فهرست بلوک معتبر نیست.');}foreach($ids as $id){if(!is_string($id)||!Security::validId($id)){throw new Problem('INVALID_INPUT','شناسه بلوک معتبر نیست.');}}
            if($type==='hero'&&++$heroCount>1){throw new Problem('INVALID_INPUT','فقط یک سربرگ اصلی برای ویترین مجاز است.');}
            $start=Policy::integer($b['starts_at']??0,0,4102444800);$end=Policy::integer($b['ends_at']??4102444800,$start+1,4102444800);$clean[]=['type'=>$type,'title'=>Policy::text($b['title']??'',180),'text'=>Policy::text($b['text']??'',4000,0),'ids'=>array_values(array_unique($ids)),'term'=>Policy::text($b['term']??'',32,0),'starts_at'=>$start,'ends_at'=>$end,'mode'=>Policy::choice($b['mode']??($ids?'manual':'auto'),['manual','auto']),'layout'=>Policy::choice($b['layout']??'rail',['rail','grid']),'count'=>Policy::integer($b['count']??12,1,20),'eyebrow'=>Policy::text($b['eyebrow']??'',180,0)];}
        $pub=$this->db->one('SELECT id FROM m_store_publication WHERE id=1 FOR UPDATE');if(\Morshed\Core\Upgrade::ready($this->db)){$draft=$this->db->one('SELECT id FROM m_store_drafts WHERE created_by=? FOR UPDATE',[$a['user_id']]);$id=$draft['id']??Security::id();$this->db->run('INSERT INTO m_store_drafts(id,created_by,blocks_json,updated_at) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE blocks_json=VALUES(blocks_json),updated_at=VALUES(updated_at)',[$id,$a['user_id'],json_encode($clean,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE),time()]);$this->audit->add($a['user_id'],'admin','store.draft_saved',$id);return $id;}$n=(int)$this->db->run('SELECT COALESCE(MAX(version_no),0)+1 FROM m_store_versions')->fetchColumn();$id=Security::id();$this->db->run('INSERT INTO m_store_versions VALUES(?,?,?,?,?)',[$id,$n,json_encode($clean,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE),$a['user_id'],time()]);$this->audit->add($a['user_id'],'admin','store.draft_created',$id);return $id;});}
    public function publishStore(array $a,string $id):void
    {$this->write($a,false,function()use($a,$id){if(\Morshed\Core\Upgrade::ready($this->db)){$draft=$this->db->one('SELECT * FROM m_store_drafts WHERE id=? FOR UPDATE',[$id]);if($draft){if($draft['created_by']!==$a['user_id']){throw new Problem('ACCESS_DENIED','پیش‌نویس متعلق به مدیر دیگری است.',403);}$n=(int)$this->db->run('SELECT COALESCE(MAX(version_no),0)+1 FROM m_store_versions')->fetchColumn();$this->db->run('INSERT INTO m_store_versions VALUES(?,?,?,?,?)',[$id,$n,$draft['blocks_json'],$a['user_id'],time()]);$this->db->run('DELETE FROM m_store_drafts WHERE id=?',[$id]);}}if(!$this->db->one('SELECT id FROM m_store_versions WHERE id=?',[$id])){throw new Problem('NOT_FOUND','نسخه پیدا نشد.',404);}$this->db->run('UPDATE m_store_publication SET version_id=?,published_at=? WHERE id=1',[$id,time()]);$this->audit->add($a['user_id'],'admin','store.published_or_restored',$id);});}
    public function store(?string $preview=null,bool $homeDefaults=false):array
    {
        $v=$preview?$this->db->one('SELECT blocks_json FROM m_store_versions WHERE id=?',[$preview]):$this->db->one('SELECT v.blocks_json FROM m_store_publication p JOIN m_store_versions v ON v.id=p.version_id WHERE p.id=1');
        if(!$v&&$preview&&\Morshed\Core\Upgrade::ready($this->db)){$v=$this->db->one('SELECT blocks_json FROM m_store_drafts WHERE id=?',[$preview]);}$blocks=json_decode($v['blocks_json']??'null',true,32,JSON_THROW_ON_ERROR);
        // Defaults use only real, published content; an explicitly empty published version stays empty.
        if($blocks===null){$blocks=$homeDefaults?$this->storeDefaults():[];}
        $out=[];foreach($blocks as $b){if(time()<$b['starts_at']||time()>=$b['ends_at']){continue;}
            $b['mode']=$b['mode']??(!empty($b['ids'])?'manual':'auto');$b['layout']=$b['layout']??'rail';$b['items']=[];
            if(in_array($b['type'],['mentors','experiences','topics'],true)){
                if($b['mode']==='manual'){foreach($b['ids'] as $id){try{
                    $item=match($b['type']){'mentors'=>$this->mentor($id),'experiences'=>$this->experience($id),'topics'=>$this->db->one("SELECT id,title,kind FROM m_terms WHERE id=? AND active=1",[$id])};
                    if($item){$b['items'][]=$item;}
                }catch(Problem $e){if($e->status!==404){throw $e;}}}}
                else{$b['items']=array_slice(match($b['type']){'mentors'=>$this->mentors(['term'=>$b['term']]),'experiences'=>$this->experiences(['term'=>$b['term']]),'topics'=>$this->terms()},0,$b['count']??12);}
            }$b['items']=array_slice($b['items'],0,$b['count']??12);$out[]=$b;
        }return $out;
    }
    public function storeDefaults():array
    {
        $out=[];foreach(['topics'=>'از کجا شروع کنیم؟','mentors'=>'مرشدها','experiences'=>'تجربه‌های خواندنی'] as $type=>$title){$out[]=['type'=>$type,'title'=>$title,'text'=>'','ids'=>[],'term'=>'','mode'=>'auto','layout'=>'rail','starts_at'=>0,'ends_at'=>4102444800];}return $out;
    }
    public function storeDraft(?string $id=null,?string $actor=null):string
    {
        $v=$id?$this->db->one('SELECT blocks_json FROM m_store_versions WHERE id=?',[$id]):$this->db->one('SELECT v.blocks_json FROM m_store_publication p JOIN m_store_versions v ON v.id=p.version_id WHERE p.id=1');
        if(\Morshed\Core\Upgrade::ready($this->db)){if($id&&!$v){$v=$this->db->one('SELECT blocks_json FROM m_store_drafts WHERE id=?',[$id]);}elseif(!$id&&$actor){$v=$this->db->one('SELECT blocks_json FROM m_store_drafts WHERE created_by=?',[$actor])??$v;}}if($id&&!$v){throw new Problem('NOT_FOUND','پیش‌نویس ویترین پیدا نشد.',404);}
        return $v['blocks_json']??json_encode($this->storeDefaults(),JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);
    }
}
